                for vtablei: usize in 0..len {
                    let offset: isize =
                        unsafe { read_i16(ptr: code.as_ptr().add(count: i + 2 + 2 * vtablei)) } as isize;
                    jumps.push(offset + i as isize + 2 + rjumpv_additional_immediates as isize);
                }
                absolute_jumpdest = jumps
            }
            opcode::CALLF => {
                let section_i: usize = unsafe { read_u16(ptr: code.as_ptr().add(count: i + 1)) } as usize;
                let Some(target_types: &TypesSection) = types.get(index: section_i) else {
                    // code section out of bounds.
                    return Err(EofValidationError::CodeSectionOutOfBounds);
                };

